#include <bits/stdc++.h>
using namespace std;
const int N = 6010;
int n, x[N], y[N];
long long solve(int u) {
  long long cnt[4] = {};
  for (int i = 1; i <= n; i++) {
    if (i == u) continue;
    int _x = abs(x[i] - x[u]), _y = abs(y[i] - y[u]);
    int id = 0;
    if (_x & 1) id += 2;
    if (_y & 1) id += 1;
    cnt[id]++;
  }
  long long sum = 0;
  sum += cnt[0] * cnt[1] + cnt[0] * cnt[2] + cnt[0] * cnt[3];
  for (int i = 0; i < 4; i++) {
    sum += (cnt[i] * (cnt[i] - 1)) / 2;
  }
  return sum;
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%d%d", &x[i], &y[i]);
    x[i] >>= 1;
    y[i] >>= 1;
  }
  long long ans = 0;
  for (int i = 1; i <= n; i++) {
    ans += solve(i);
  }
  printf("%lld\n", ans / 3);
  getchar();
  getchar();
  return 0;
}

