/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Roy
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        D1DominoEasyVersion solver = new D1DominoEasyVersion();
        solver.solve(1, in, out);
        out.close();
    }

    static class D1DominoEasyVersion {
        private boolean found;

        private void solveEvenXEvenMatrix(int dominoes) {
            //~ if the matrix is: even x even
            //~ then it is enough to check the number of dominoes are even or not
            if (dominoes % 2 == 0) found = true;
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int tc = in.readInteger();
            for (int cs = 1; cs <= tc; ++cs) {
                int n = in.readInteger();
                int m = in.readInteger();
                int k = in.readInteger();

                found = false;
                if (n % 2 == 0 && m % 2 == 0) {//~ even x even matrix
                    solveEvenXEvenMatrix(k);
                } else if (n % 2 == 0 && m % 2 == 1) {//~ even x odd matrix
                    int maxPossibleHorizons = (m * n) / 2 - (n / 2);

                    if (k <= maxPossibleHorizons) {//~ k should not be > maxPossibleHorizons
                        solveEvenXEvenMatrix(k);
                    }
                } else if (n % 2 == 1 && m % 2 == 0) { //~ odd x even matrix
                    int leastHorizons = m / 2;
                    if (k >= leastHorizons) {
                        int restHorizons = k - leastHorizons;
                        solveEvenXEvenMatrix(restHorizons);
                    }
                }
                if (found) out.printLine("YES");
                else out.printLine("NO");
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);

                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInteger() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            this.print(objects);
            writer.println();
        }

        public void close() {
            writer.flush();
            writer.close();
        }

    }
}

