    static final long MOD = 1000000007L;
    static ArrayDeque<Integer>[] edges;

    public static void main(String[] args) {
        int t = in.nextInt();
        while (t-- != 0) {
            solve();
        }
    }

    public static void solve() {
        int N = in.nextInt();
        int K = in.nextInt();
        edges = new ArrayDeque[N];
        for(int i=0; i < N; i++)
            edges[i] = new ArrayDeque<Integer>();
        for(int i=1; i < N; i++)
        {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            edges[a].add(b);    edges[b].add(a);
        }
        long res = 0L;
        if(K == 2)
            res = N*(N-1)/2;
        else
        {
            for(int center=0; center < N; center++)
            {
                int[] label = new int[N];
                int[] depth = new int[N];
                ArrayDeque<Integer> q = new ArrayDeque<Integer>();
                q.add(center);
                Arrays.fill(depth, -1);
                depth[center] = 0;
                while(q.size() > 0)
                {
                    int curr = q.poll();
                    for(int next: edges[curr])
                        if(depth[next] == -1)
                        {
                            depth[next] = depth[curr]+1;
                            if(curr == center)
                                label[next] = next;
                            else
                                label[next] = label[curr];
                            q.add(next);
                        }
                }
                //dp stuff
                int[][] freq = new int[N][N];
                for(int v=0; v < N; v++)
                    if(v != center)
                        freq[depth[v]][label[v]]++;
                for(int d=0; d < N; d++)
                {
                    long[] dp = new long[K+1];
                    dp[0] = 1L;
                    for(int v=0; v < N; v++)
                        if(freq[d][v] > 0)
                            for(int i=K; i > 0; i--)
                            {
                                dp[i] += (freq[d][v]*dp[i-1])%MOD;
                                if(dp[i] >= MOD)
                                    dp[i] -= MOD;
                            }
                    res += dp[K];
                    if(res >= MOD)
                        res -= MOD;
                }
            }
        }
        System.out.println(res);
    }
}

