int n;
int k;
int f_[210];
vector<pair<int, int> > chords;
void solve() {
  for (int i = 0; i < 210; i++) {
    f_[i] = 1;
  }
  int free = 2 * n;
  for (auto pr : chords) {
    f_[pr.first] = 0;
    f_[pr.second] = 0;
    free -= 2;
  }
  int points = (n - k) * (n - k - 1) / 2;
  for (int i = 0; i < k; i++) {
    int x = chords[i].first, y = chords[i].second;
    if (x > y) swap(x, y);
    for (int j = i + 1; j < k; j++) {
      int u = chords[j].first, v = chords[j].second;
      if ((x < u && u < y) ^ (x < v && v < y)) points++;
    }
    int cnt = 0;
    for (int j = x + 1; j < y; j++) {
      if (f_[j] == 1) cnt++;
    }
    points += min(cnt, free - cnt);
  }
  cout << points;
  cout << "\n";
}
