				nums[i] = Math.abs(in.nextInt());
			}
			boolean good = false;
			for(int i = 0; i < n; i++) {
				good |= check(0, i, 0, nums);
			}
			System.out.println(good ? "YES" : "NO");
		}
		in.close();
	}

	public static boolean check(int curr, int skip, int total, int[] nums) {
		if(total == nums[skip]) {
			return true;
		}
		if(curr >= nums.length) {
			return false;
		}
		if(curr == skip)
			return check(curr+1, skip, total, nums);
		return check(curr+1, skip, total, nums) || check(curr+1, skip, total+nums[curr], nums) || check(curr+1, skip, total-nums[curr], nums);
	}

}

