    void work() {
        int n=ni();
        TreeMap<Integer,Long> tree=new TreeMap<>();
        int[][] A=new int[n+1][3];
        for(int i=1;i<=n;i++){
            A[i]=new int[]{ni(),ni(),ni()};
        }
        long ret=0;
        long cur=1;
        Integer last=A[n][0]+1;
        for(int i=n;i>=0;i--){
            Integer pre=tree.lowerKey(last);
            while(pre!=null&&pre>A[i][0]){
                long c=tree.get(pre);
                ret+=cur*(last-pre);
                ret%=mod;
                cur-=c;
                last=pre;
                pre=tree.lowerKey(last);
            }
            ret=ret+cur*(last-A[i][0]);
            ret%=mod;
            long cur2=cur*2;
            if(A[i][2]==0){
                cur2--;
            }
            tree.put(A[i][1],cur2-cur);
            last=A[i][0];
            cur=cur2;
            cur%=mod;
