public class ReverseString1553B {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int testNo = sc.nextInt();
		sc.nextLine();
		for(int i=0;i<testNo;i++){
			String s = sc.nextLine();
			String t = sc.nextLine();

			System.out.println(checkReverseString(s,t));
		}

	}

	private static String checkReverseString(String s, String t) {
		boolean result = false;
		for(int i=0;i<s.length();i++){
			if(s.charAt(i) == t.charAt(0) && !result){
				result = checkForPosition(s, t, i, 1, 0);
			}
		}
		if(result){
			return "Yes";
		}

		return "No";
	}

	private static boolean checkForPosition(String s, String t, int index, int move, int len) {
		if(len == t.length()){
			return true;
		}
		if(index<0 || index>= s.length() || s.charAt(index) != t.charAt(len)){
			return false;
		}
		if(move == 1){
			return checkForPosition(s, t, index+ move, 1, len+1) || checkForPosition(s, t, index-1, -1, len+1);
		} else {
			return checkForPosition(s, t, index-1, -1, len+1);
		}

	}

}

