import java.util.*;
import java.io.*;

public class A1553 {
	public static int[] rotateLeft(int[] arr, int k) {
		int n = arr.length;
		int[] res = new int[n];
		for (int i = 0; i < n; i++) {
			res[i] = arr[(i + k) % n];
		}
		return res;
	}

	public static int solve(int[] arr) {
		int comp = 0;
		boolean[] vis = new boolean[arr.length];
		for (int i = 0; i < arr.length; i++) {
			if (!vis[i]) {
				comp++;
				int cur = i;
				while (!vis[cur]) {
					vis[cur] = true;
					cur = arr[cur];
				}
			}
		}
//		System.out.println(Arrays.toString(arr) + " " + (arr.length - comp));

		return arr.length - comp;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
		int t = sc.nextInt();
		while (t-- > 0) {
			int n = sc.nextInt();
			int m = sc.nextInt();
			int[] arr = sc.nextIntArr(n);
			for (int i = 0; i < arr.length; i++) {
				arr[i]--;
			}
			int[] cnt = new int[n];
			for (int i = 0; i < arr.length; i++) {
				cnt[(i - arr[i] + n) % n]++;
			}
			int still = n - 2 * (n / 3);
			ArrayList<Integer> ans = new ArrayList<Integer>();
			for (int i = 0; i < n; i++) {
				if (cnt[i] >= still) {
					if (solve(rotateLeft(arr, i)) <= m) {
						ans.add(i);
					}
				}
			}
			pw.print(ans.size());
			for (int x : ans) {
				pw.print(" " + x);
			}
			pw.println();
		}
		pw.close();
	}

