          a.add(new Triple(x,y,z));
      }
      Collections.sort(a);
      SEG seg= new SEG();
      int L=0;
      int ans= Integer.MAX_VALUE;
      for(int R=0;R<n;R++) {
          seg.update(1,1,m,a.get(R).y,a.get(R).z,1);
          while(true) {
            seg.update(1, 1, m, a.get(L).y, a.get(L).z, -1);
            if (seg.tree[1] > 0) {
                L++;
                continue;
            }
            seg.update(1, 1, m, a.get(L).y, a.get(L).z, 1);
            break;
          }
          if(seg.tree[1]>0) ans= Math.min(ans, a.get(R).x-a.get(L).x);
      }
      System.out.println(ans);
    }

