class Triple implements Comparable<Triple>{
    public int x;
    public int y;
    public int z;
    public Triple(int x, int y, int z){
        this.x = x;this.y = y;this.z = z;
    }
    public int compareTo(Triple o){
        if(this.x!=o.x) return this.x-o.x;
        if(this.y!=o.y) return this.y-o.y;
        return this.z-o.z;
    }
}

class SEG {
    int MAXN= 1000100;
    public int[] tree= new int[4*MAXN], lazy= new int[4*MAXN];
    void push(int i, int L, int R){
        if(lazy[i]==0) return;
         tree[i] += lazy[i];
        if (L != R) {
            lazy[i << 1] += lazy[i];
            lazy[i << 1 | 1] += lazy[i];
        }
        lazy[i] = 0;
    }
    //update a[i]+= val for all i in [u,v]
    public void update(int i, int L, int R, int u, int v, int val) {
        push(i,L,R);
        if(L>v || R<u) return;
        if(L>=u && R<=v) {
            lazy[i] = val;
            push(i,L,R);
            return;
        }
        int mid= (L+R)>>1;
        update(i << 1, L, mid, u, v, val);
        update(i << 1 | 1, mid + 1, R, u, v, val);
        tree[i] = Math.min(tree[i << 1], tree[i << 1 | 1]);
    }
}

