#include <bits/stdc++.h>
using namespace std;
long long int pow_cal[200001];
long long int power(long long int a, long long int b) {
  long long int res = 1;
  while (b > 0) {
    if (b & 1) res = (res * a) % 1000000007;
    a = (a * a) % 1000000007;
    b /= 2;
  }
  return res % 1000000007;
}
long long int abc(long long int n, long long int k) {
  if (n == 1) return pow_cal[k];
  if (k == 0) return 1;
  if (n & 1) {
    long long int x = (pow_cal[n - 1] + 1) % 1000000007;
    x = power(x, k);
    return x;
  } else {
    if (k == 1) return pow_cal[n - 1];
    long long int x = power(pow_cal[n], k - 1);
    x = x + ((pow_cal[n - 1] - 1) * (abc(n, k - 1))) % 1000000007;
    x %= 1000000007;
    return x;
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  pow_cal[0] = 1;
  for (int i = 1; i < 200001; i++) {
    pow_cal[i] = (2 * pow_cal[i - 1]) % 1000000007;
  }
  int T;
  cin >> T;
  while (T--) {
    long long int n, k;
    cin >> n >> k;
    cout << abc(n, k) << '\n';
  }
}

