        }
      } else {
        for (long long int j = 1; j < n - 1; j += 2) {
          if (a[j] > a[j + 1]) swap(a[j], a[j + 1]);
        }
      }
      p ^= 1;
      ans++;
    }
    cout << ans << "\n";
  }
  return 0;
}

