        for(int t = 0; t < T; t++){
            int a = Integer.parseInt(sc.next());
            int b = Integer.parseInt(sc.next());

            if(a > b){
                int tmp = a;
                a = b;
                b = tmp;
            }

            var list = new ArrayList<Integer>();
            if((a+b) % 2 == 0){
                int holdA = a;
                int breakA = 0;
                int holdB = (a+b)/2;
                int breakB = (a+b)/2 - a;
                list.add(breakB);
                while(holdA > 0){
                    holdA--;
                    breakA++;
                    holdB--;
                    breakB++;
                    list.add(breakA + breakB);
                }
            }else{
                int holdA = a;
                int breakA = 0;
                int holdB = (a+b)/2;
                int breakB = (a+b)/2 + 1 - a;
                list.add(breakB);
                while(holdA > 0){
                    holdA--;
                    breakA++;
                    holdB--;
                    breakB++;
                    list.add(breakA + breakB);
                }

                holdA = a;
                breakA = 0;
                holdB = (a+b)/2 + 1;
                breakB = (a+b)/2 - a;
                list.add(breakB);
                while(holdA > 0){
                    holdA--;
                    breakA++;
                    holdB--;
                    breakB++;
                    list.add(breakA + breakB);
                }
            }
