	public static long solution(long n, long m)	{

		long[] dp = new long[(int)n];

		if(n==1)
			return 1;
		if(n==2)
			return 2;		

		dp[0] = 1;
		dp[1] = 2;
		dp[2] = 5;

		long prev = 8;

		for(int i = 3; i<n; i++)
		{
			long num = i+1;
			dp[i] = prev%m;			
			long b = num;
			int y = 1;
			int j = 2;

			for(j = 2; j*j<=num; j++)
			{
				 long x = num/j; // x is possibly the largest number for which num/x == j
				 dp[i] = (dp[i]%m + dp[(int)x-1]%m)%m;

				  dp[i] = (dp[i]%m + ((b-x)%m * dp[y-1]%m )%m)%m;
				  b = x;
				  y = j;
			}

			dp[i] = (dp[i]%m + ((b-j+1)%m * dp[y-1]%m )%m)%m;
			prev = (prev%m + dp[i]%m)%m;

		}		

		return dp[(int)n-1];

	}


