bool found(string& s, vector<long long int>& a) {
  if (s.length() < a.size()) {
    return false;
  }
  long long int idx = 0;
  for (long long int dig : a) {
    bool f = false;
    while (idx < s.length()) {
      long long int d = s[idx] - '0';
      if (d == dig) {
        f = true;
        idx++;
        break;
      }
      idx++;
    }
    if (!f) {
