template <class S, S (*op)(S, S), S (*e)()>
struct segtree {
 public:
  segtree() : segtree(0) {}
  explicit segtree(int n) : segtree(std::vector<S>(n, e())) {}
  explicit segtree(const std::vector<S> &value) : n(int(value.size())) {
    log = 32 - __builtin_clz(n);
    size = 1 << log;
    data = std::vector<S>(2 * size, e());
    for (int i = 0; i < n; i++) {
      data[size + i] = value[i];
    }
    for (int i = size - 1; i >= 1; i--) {
      update(i);
    }
  }
  void set(int p, S x) {
    p += size;
    data[p] = x;
    for (int i = 1; i <= log; i++) {
      update(p >> i);
    }
  }
  S get(int p) { return data[p + size]; }
  S prod(int l, int r) {
    S sml = e(), smr = e();
    for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
      if (l & 1) {
        sml = op(sml, data[l++]);
      }
      if (r & 1) {
        smr = op(data[--r], smr);
      }
    }
    return op(sml, smr);
  }
  S all_prod() { return data[1]; }

 private:
  int n, size, log;
  std::vector<S> data;
  void update(int k) { data[k] = op(data[2 * k], data[2 * k + 1]); }
};
