import java.io.*;
import java.util.*;

public class D {

	public static void main(String[] args) throws IOException {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

		int t = Integer.parseInt(br.readLine());

		while(t --> 0) {

			StringTokenizer st = new StringTokenizer(br.readLine());

			int n = Integer.parseInt(st.nextToken());
			int m = Integer.parseInt(st.nextToken());

			st = new StringTokenizer(br.readLine());

			ArrayList<Person> people = new ArrayList<Person>();

			for(int i = 0; i < n*m; i++) {

				people.add(new Person(i, Integer.parseInt(st.nextToken())));

			}

			Collections.sort(people, new Comp());

			//System.out.println(people);

			int[] locations = new int[n*m];
			PriorityQueue<Integer> pq = new PriorityQueue<Integer>(new SeatComp(m));

			for(int i = 0; i < people.size(); i++) {

				if(pq.isEmpty()) {

					for(int j = i; j < people.size(); j++) {

						if(people.get(j).a != people.get(i).a)
							break;

						pq.add(j);

					}

				}

				//System.out.println(pq);

				locations[people.get(i).n] = pq.poll();

			}

			long sum = 0;
			FenwickTree tree = new FenwickTree(n*m);

			for(int i = 0; i < n*m; i++) {

				int row = Math.floorDiv(locations[i], m) * m;								
				sum += tree.sum(row, locations[i]);				
				tree.add(locations[i], 1);

			}

			pw.println(sum);

		}

		pw.flush();

	}

	static class FenwickTree{

		long[] bit;
		int n;

		public FenwickTree(int n) {

			this.n = n;
			bit = new long[n];

		}

		public long sum(int r) {

			long ret = 0;
	        for (; r >= 0; r = (r & (r + 1)) - 1)
	            ret += bit[r];
	        return ret;

		}

	    public long sum(int l, int r) {

	        return sum(r) - sum(l - 1);

	    }

	    public void add(int idx, long delta) {

	        for (; idx < n; idx = idx | (idx + 1))
	            bit[idx] += delta;

	    }

	}

	static class Person {

		int n, a;

		@Override
		public String toString() {
			// TODO Auto-generated method stub
			return n + " " + a;
		}

		public Person(int n, int a) {

			this.n = n;
			this.a = a;

		}

	}

	static class Comp implements Comparator<Person>{

		@Override
		public int compare(Person a, Person b) {

			if(a.a == b.a) {

				return Integer.compare(b.n, a.n);

			}

			return Integer.compare(a.a, b.a);

		}

	}

	static class SeatComp implements Comparator<Integer>{

		int m;

		public SeatComp(int m) {

			this.m = m;

		}

		@Override
		public int compare(Integer a, Integer b) {

			if(a/m == b/m) {

				return Integer.compare(a%m, b%m);

			}

			return Integer.compare(b, a);

		}

	}

}

