      dp[i] = 0;
      leaves[i] = 0;
    }
    for (long long i = 0; i < n - 1; i++) {
      long long u, v;
      cin >> u >> v;
      u--;
      v--;
      g[u].push_back(v);
      g[v].push_back(u);
    }
    dfs(0, -1);
    cout << leaves[0] << '\n';
  }
  return 0;
}

