using namespace std;
int getXor(int n) {
  switch (n % 4) {
    case 0:
      return n;
    case 1:
      return 1;
    case 2:
      return n + 1;
    case 3:
      return 0;
  }
}
void solve() {
  int a, b;
  cin >> a >> b;
  int xr = getXor(a - 1), need = b;
  bitset<32> bs1(xr), bs2(need);
  int ans = 0;
  for (int bit = 0; bit < 32; bit++)
    if (bs2[bit]) {
      ans += (1LL << bit) * !bs1[bit];
    } else {
      ans += (1LL << bit) * bs1[bit];
    }
  cout << a + (ans == a) + (getXor(a - 1) != b) << '\n';
}
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  int t = 1;
  cin >> t;
  while (t--) solve();
  return 0;
}

