import java.io.*;
import java.util.*;

public class CF1567E extends PrintWriter {
	CF1567E() { super(System.out); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF1567E o = new CF1567E(); o.main(); o.flush();
	}

	long[] ss;
	int[] kk, kp, kq, ap, aq; int n_;
	void pul(int i) {
		int l = i << 1, r = l | 1;
		ap[i] = ap[l]; aq[i] = aq[r];
		ss[i] = ss[l] + ss[r];
		if (aq[l] > ap[r]) {
			kp[i] = kp[l];
			kq[i] = kq[r];
		} else {
			kp[i] = kp[l] < kk[l] ? kp[l] : kk[l] + kp[r];
			kq[i] = kq[r] < kk[r] ? kq[r] : kk[r] + kq[l];
			ss[i] += (long) kq[l] * kp[r];
		}
	}
	void build(int[] aa, int n) {
		n_ = n;
		ss = new long[n_ * 2];
		kk = new int[n_ * 2]; kp = new int[n_ * 2]; kq = new int[n_ * 2];
		ap = new int[n_ * 2]; aq = new int[n_ * 2];
		for (int i_ = 0; i_ < n; i_++) {
			int i = n_ + i_;
			ap[i] = aq[i] = aa[i_];
			ss[i] = kk[i] = kp[i] = kq[i] = 1;
		}
		for (int i = n - 1; i > 0; i--) {
			kk[i] = kk[i << 1] + kk[i << 1 | 1];
			pul(i);
		}
	}
	void update(int i, int a) {
		i += n_;
		ap[i] = aq[i] = a;
		while (i > 1)
			pul(i >>= 1);
	}
	long query(int l, int r) {
		long s = 0;
		int al = 0x3f3f3f3f, ar = 0, kl = 0, kr = 0;
		for (l += n_, r += n_; l <= r; l >>= 1, r >>= 1) {
			if ((l & 1) == 1) {
				s += ss[l];
				if (al <= ap[l])
					s += (long) kl * kp[l];
				if (kq[l] == kk[l] && al <= ap[l])
					kl += kk[l];
				else
					kl = kq[l];
				al = aq[l];
				l++;
			}
			if ((r & 1) == 0) {
				s += ss[r];
				if (aq[r] <= ar)
					s += (long) kq[r] * kr;
				if (kp[r] == kk[r] && aq[r] <= ar)
					kr += kk[r];
				else
					kr = kp[r];
				ar = ap[r];
				r--;
			}
		}
		if (al <= ar)
			s += (long) kl * kr;
		return s;
	}
	void main() {
		int n = sc.nextInt();
		int q = sc.nextInt();
		int[] aa = new int[n];
		for (int i = 0; i < n; i++)
			aa[i] = sc.nextInt();
		build(aa, n);
		while (q-- > 0) {
			int t = sc.nextInt();
			if (t == 1) {
				int i = sc.nextInt() - 1;
				int a = sc.nextInt();
				update(i, a);
			} else {
				int l = sc.nextInt() - 1;
				int r = sc.nextInt() - 1;
				println(query(l, r));
			}
		}
	}
}

