	    public MyScanner() {
	       br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() {
	        while (st == null || !st.hasMoreElements()) {
	            try {
	                st = new StringTokenizer(br.readLine());
	            } catch (IOException e) {
	                e.printStackTrace();
	            }
	        }
	        return st.nextToken();
	    }

	    int nextInt() {
	        return Integer.parseInt(next());
	    }

	    long nextLong() {
	        return Long.parseLong(next());
	    }

	    double nextDouble() {
	        return Double.parseDouble(next());
	    }

	    String nextLine(){
	        String str = "";
		  try {
		     str = br.readLine();
		  } catch (IOException e) {
		     e.printStackTrace();
		  }
		  return str;
	    }

	 }

    public static long[] fact;
    public static long m = 998244353;

    public static void find()
    {
    	fact[0] = 1;
    	for(int i = 1; i<=200000; i++)
    	   fact[i] = (fact[i-1] * i)%m;

    }

    public static long expo (long a) {

    	long res = 1;
    	long b = m-2;
    	while(b>0)
    	{
    		if(b%2==1)
    			res = (res * a)%m;
    		a = (a * a)%m;
    		b/=2;
    	}

    	return res;
    }

	public static long solution(int[] arr, int n)

	{
		int max1 = Integer.MIN_VALUE;

		for(int i = 0; i<n; i++)
		{
			if(arr[i]>max1)
				max1 = arr[i];
		}

        int max2 = Integer.MIN_VALUE;

		for(int i = 0; i<n; i++)
		{
			if(arr[i]>max2 && arr[i]<max1)
				max2 = arr[i];
		}

		if(max2 == Integer.MIN_VALUE)
			return fact[n];

		int num  = 0;
		int c = 0;

		for(int i = 0; i<n; i++)
		{
			if(arr[i]==max2)
				num++;
			if(arr[i]==max1)
				c++;
		}

		long ans = 0;

		if(c>1)
			return fact[n];

		if(max1-max2>1)
			return 0;

		for(int i = num; i<n; i++)
			ans = (ans + ( (fact[i]*expo(fact[i-num]))%m * (fact[n-num-1]) )%m )%m;

		return (fact[n] - ans + m)%m;

	}

private static PrintWriter out = new PrintWriter(System.out);

public static void main (String[] args)
{
	MyScanner s =  new MyScanner();
    fact = new long[200001];
