                    do_op(0)
        else:
            x = i
            while x >= 1:
                do_op(x-1)
                x -= 2
    p = 1
    while p+1 < n:
        if a[p] != a[p+1]:
            do_op(p)
            if a[p] == 0:
                p += 2
