        while (t-- != 0) {
            long a = in.nextLong(), b = in.nextLong(), c = in.nextLong(), m = in.nextLong();
            long[] arr = {a, b, c};
            Arrays.sort(arr);
            if (m > (a - 1 + b - 1 + c - 1)) {
                System.out.println("NO");
            } else {
                long value = arr[2] - (arr[1] + arr[0] + 1);
                if (value <= m) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    public static boolean isPrime(long num) {
        if (num <= 1) {
            return false;
        } else {
            long sq = (long) Math.sqrt(num) + 1;
            for (long i = 2; i < sq; i++) {
                if (num % i == 0) {
                    return false;
                }
            }
            return true;
        }
    }

    public static boolean checkPalindrome(String x) {
        String temp = "";
        if (x.length() % 2 == 0) {
            for (int i = x.subSequence(x.length() / 2, x.length()).length() - 1; i >= 0; i--) {
                temp += x.subSequence(x.length() / 2, x.length()).charAt(i);
            }
            return x.substring(0, x.length() / 2).equals(temp);
        } else {
            for (int i = x.subSequence(x.length() / 2, x.length()).length() - 1; i > 0; i--) {
                temp += x.subSequence(x.length() / 2, x.length()).charAt(i);
            }
            return x.substring(0, x.length() / 2).equals(temp);
        }
    }

    public static void sub(String s, String ans) {
        if (s.length() == 0) {
            arr.add(ans);
            return;
        }
        sub(s.substring(1), ans + s.charAt(0));
        sub(s.substring(1), ans);
    }

    public static long gcd(long a, long b) {
        if (a == 0) {
            return b;
        }
        return gcd(b % a, a);
    }

    public static long lcm(long a, long b) {
        return (a / gcd(a, b)) * b;
    }
}

