                ans = Math.min(ans , getAns(x, y, tot - arr[attacker - 1], arr[attacker - 1]));
            System.out.println(ans);
        }
    }

    public static long getAns(long x, long y, long tot, long atk) {
        long ans = Math.max(0, x - atk);
        ans += Math.max(0, y - tot);
        return ans;       
    }
}
