        List<Integer> start = new ArrayList<>();
        for(int i = 0; i < n ;i ++ ) {
            String[] cstr = rd.readLine().split(" ");
            for(int j = 0;j < cstr.length ;j ++ ) {
                c[i][j] = Integer.parseInt(cstr[j]);
            }
            start.add(c[i][0]);
        }
        int m = Integer.parseInt(rd.readLine());
//        int[][] b = new int[m][n];
        Set<List> banner = new HashSet<>();
        Set<List> vis = new HashSet<>();
        for(int i = 0; i < m ;i ++ ) {
            String[] bstr = rd.readLine().split(" ");
            List<Integer> list = new ArrayList<>();
            for(int j = 0;j < bstr.length ;j ++ ) {
                list.add(Integer.parseInt(bstr[j]));
            }
            banner.add(list);
        }

        PriorityQueue<List<Integer>> queue = new PriorityQueue<>((o1,o2)->{
            int sum1 = 0, sum2 = 0;
            for(int i = 0; i < n; i ++) sum1 += c[i][o1.get(i)];
            for(int i = 0; i < n; i ++) sum2 += c[i][o2.get(i)];
            return sum2 - sum1;
        });
        queue.add(start);
        while(!queue.isEmpty()) {
            List<Integer> t = queue.poll();
            for(int i = 0; i < n; i ++) {
                List<Integer> newt = new ArrayList<>(t);
                if(newt.get(i) != 1) {
                    newt.set(i, newt.get(i) - 1);
