public class J{

	static int n,m;
	static int[][] a,nxt;

	static int row,col;

	static void upd(int i, int j) {
		a[i][j] = 2;
		if (i == n-1) nxt[i][j] = n;
		else nxt[i][j] = nxt[i+1][j];

		if (i != 0 && a[i-1][j] == 2) {
			nxt[i-1][j] = nxt[i][j];
		}
	}

	static void move() {
	//System.out.println(row + " " + col);
		if (a[row][col] == 1) {
			upd(row,col);
			col++;
		}
		else if (a[row][col] == 3) {
			upd(row,col);	
			col--;
		}
		else {
			// Move down to next position
			row = nxt[row][col];
		}
	}

