            for(int i=0;i<n;i++){
                str[i]=in.next();
            }
            ttt=0;
            map=new int[n+1][m+1];
            for(int i=0;i<=n;i++){
                for(int j=0;j<=m;j++){
                    map[i][j]=0;
                }
            }
            for(int i=0;i<n;i++){
                for(int j=0;j<str[i].length();j++){
                    if(str[i].charAt(j)=='*')ttt++;
                }
            }
            for(int i=n-1;i>=k;i--){
                for(int j=0;j<str[i].length();j++){
                    if(str[i].charAt(j)=='*'){
                        int jud=judge(i,j,m);
                        if(jud>=k){
                            change(i,j,jud,m);
                        }
                    }
                }
            }
            if(ttt!=0){
                System.out.println("NO");
            }else{
                System.out.println("YES");
            }
        }
    }
    static void change(int i,int j,int k,int m){
        boolean flag=true;
        int res=0;
        while(flag){
            if(i-res<0 || j-res<0 ||res>k) {
                break;
            }
            if(str[i-res].charAt(j-res)=='*'){
                if(map[i-res][j-res]==0){
                    map[i-res][j-res]=1;
                    ttt--;
                }
                res++;
            }else{
                break;
            }
        }
        int res1=0;
        while(flag){
            if(i-res1<0 || j+res1>=m ||res1>k) {
                break;
            }
            if(str[i-res1].charAt(j+res1)=='*'){
                if(map[i-res1][j+res1]==0){
                    map[i-res1][j+res1]=1;
                    ttt--;
                }
                res1++;
            }else{
                break;
            }
        }
    }
    static int judge(int i,int j,int m){
        int res=0;
        boolean flag=true;
        while(flag){
            if(i-res<0 || j-res<0) {
                break;
            }
            if(str[i-res].charAt(j-res)=='*'){
                res++;
            }else{
                break;
            }
        }
        int res1=0;
        while(flag){
            if(i-res1<0 || j+res1>=m) {
                break;
            }
            if(str[i-res1].charAt(j+res1)=='*'){
                res1++;
            }else{
                break;
            }
        }
        return Math.min(res-1,res1-1);
    }
}

