		while(t-->0) {
			list=new ArrayList<>();
			int n=sc.nextInt();
			String s=sc.next();
			int l=0,r=n-1;
			while(l<r) {
				if(s.charAt(l)!=s.charAt(r)) {
					break;
				}
				l++;
				r--;
			}
			if(l>=r) {
				System.out.println(0);
				continue;
			}
			String a,b;
			int ans=Integer.MAX_VALUE;
			boolean flag=false;
			int res1=cp(s,s.charAt(l));
			if(res1!=-1) {
				ans=res1;
				flag=true;
			}
			int res2=cp(s,s.charAt(r));
			if(res2!=-1) {
				ans=Math.min(ans, res2);
				flag=true;
			}
			if(!flag) {
				System.out.println(-1);
			}
			else {
				//System.out.println(res1+" "+res2);
				System.out.println(ans);
			}
		}
	}
	static int cp(String s,char ch) {
		int l=0,r=s.length()-1,count=0;
		while(l<r) {
			if(s.charAt(l)!=s.charAt(r)) {
				boolean flag = false;
				if(s.charAt(l)==ch) {
					l++;
					flag=true;
				}
				else if(s.charAt(r)==ch) {
					r--;
					flag=true;
				}
				count++;
				if(!flag) {
					return -1;
				}
			}
			else {
				l++;
				r--;
			}
		}
		return count;
	}
}

