public class _751 {
    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int t = 1;
        int MAX = 8194;
        int poss = 8192;
        while (t-- > 0) {
            int n = sc.nextInt();
            int [] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextInt();
            int [] min = new int[MAX];
            Arrays.fill(min, n + 1);
            ArrayList<Pair> b = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                b.add(new Pair(i, a[i]));
            }
            Collections.sort(b);
            int cur = 0;
            min[0] = -1;
            int count = 1;
            for (int i = 0; i < MAX; i++) {
                TreeSet<Integer> set = new TreeSet<>();
                while (cur < b.size() && b.get(cur).x == i) {
                    set.add(b.get(cur).i);
                    ++cur;
                }
                if (set.size() == 0) continue;
                for (int j = 0; j < MAX; j++) {
                    if (min[j] != n + 1) {
                        Integer high = set.higher(min[j]);
                        if (high != null) {
                            int v = i ^ j;
                            if (min[v] == n + 1) ++count;
                            min[v] = Math.min(min[v], high);
                        }
                    }
                }
                if (count == poss) break;
            }
            ArrayList<Integer> res = new ArrayList<>();
            for (int i = 0; i < MAX; i++) {
                if (min[i] != n + 1) {
                    res.add(i);
                }
            }
            out.println(res.size());
            for (Integer x: res) out.print(x + " ");
        }
        out.close();
    }

    static class Pair implements Comparable<Pair> {
        int i; int x;
        Pair(int i, int x) {
            this.i = i; this.x = x;
        }

        @Override
        public int compareTo(Pair o) {
            if (x == o.x) return Integer.compare(i, o.i);
            return Integer.compare(x, o.x);
        }
    }




    static void sort(int[] a) {
        ArrayList<Integer> q = new ArrayList<>();
        for (int i : a) q.add(i);
        Collections.sort(q);
        for (int i = 0; i < a.length; i++) a[i] = q.get(i);
    }

    static void sort(long[] a) {
        ArrayList<Long> q = new ArrayList<>();
        for (long i : a) q.add(i);
        Collections.sort(q);
        for (int i = 0; i < a.length; i++) a[i] = q.get(i);
    }


