        while (t-- > 0) {
            String [] inp = buffer.readLine().split(" ");
            int n = Integer.parseInt(inp[0]), k = Integer.parseInt(inp[1]);
            inp = buffer.readLine().split(" ");
            int [] arr = new int[n];
            ArrayList<Integer>positives = new ArrayList<>(), negatives = new ArrayList<>();
            int max = 0;
            for (int i = 0; i < n; i++) {
                arr[i] = Integer.parseInt(inp[i]);
                if (arr[i] >= 0)
                    positives.add(arr[i]);
                else
                    negatives.add(-arr[i]);
                max = Math.max(max, Math.abs(arr[i]));
            }
            Collections.sort(positives);
            Collections.sort(negatives);
            int lenP = positives.size(), lenN = negatives.size();
            long ans = 0;
            for (int i = lenP-1; i >= 0; i-=k) {
                ans += positives.get(i);
            }
            for (int i = lenN-1; i >= 0; i-=k) {
                ans += negatives.get(i);
            }
            ans *= 2;
            ans -= max;
            sb.append(ans).append("\n");
        }
        System.out.println(sb);
    }
}

