import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;

public class D {

    static class Pair{
        int dest;
        int weight;
        Pair(int a,int b){
            this.dest = a;
            this.weight=b;
        }
    }
    static ArrayList<ArrayList<Pair>> adjl;
    static int[] color;
    static boolean ok;
    static int[] c;
    // 0 - imposters, 1-crew
    static void dfs(int v){
        c[color[v]]++;
        for(Pair child:adjl.get(v)){
            if(color[child.dest]==-1){
                color[child.dest]=color[v]^child.weight;
                dfs(child.dest);
            } else if((color[v]^child.weight)!=color[child.dest]){
                ok=false;
            }
        }
    }
    public static void main(String[] args)
    {
        FastScanner sc=new FastScanner();
        int t=sc.nextInt();
        PrintWriter pw=new PrintWriter(System.out);
        while(t-->0) {
            int n=sc.nextInt();
            adjl=new ArrayList<>();
            ok=true;
            c=new int[2];
            color=new int[n];
            Arrays.fill(color,-1);
            for(int i=0;i<n;i++){
                adjl.add(new ArrayList<>());
            }
            int m=sc.nextInt();
            for(int i=0;i<m;i++){
                int src=sc.nextInt()-1;
                int dest=sc.nextInt()-1;
                String type=sc.next();
                if(type.equals("imposter")){
                    adjl.get(src).add(new Pair(dest,1));
                    adjl.get(dest).add(new Pair(src,1));
                } else {
                    adjl.get(src).add(new Pair(dest,0));
                    adjl.get(dest).add(new Pair(src,0));
                }
            }
            int ans=0;
            for(int i=0;i<n;i++){
                if(color[i]==-1){
                    color[i]=0;
                    c[0]=0;
                    c[1]=0;
                    dfs(i);
                    ans+=Math.max(c[0],c[1]);
                }
            }
            if(!ok){
                pw.println(-1);
            } else {
                pw.println(ans);
            }
        }
        pw.flush();
    }

    static class FastScanner {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer("");
