def powerm(a, b): 
    # calculate a ** b % MOD
    prodi = 1
    base = a
    while b:
        if b % 2 == 1:
            prodi = (prodi * base) % MOD
        base = (base * base) % MOD
        b = b >> 1
    return prodi

def under(node, k):
    # count number ways to color nodes under node excluding node, k: total height
    num_nodes = 2 ** (k - node.bit_length() + 1) - 2
    return powerm(4, num_nodes)

