import java.math.BigInteger;
import java.util.*;
import java.io.*;

public class Div743 {
    static HashMap<Long, Integer>[] dp;
    static long[] a;
    static int k, mod = (int) 1e9 + 7;
    static long Max;
    static HashMap<Long, Integer> done;
    static HashSet<Long> in;

    static boolean exist(long idx) {
        return in.contains(idx);
//        return false;
    }

    static long[] solvememo;

    static long solve(int pow) {
        if (pow == 0)
            return 1;
        if (solvememo[pow] != -1)
            return solvememo[pow];

        long ans = 4 * solve(pow - 1) * solve(pow - 1);
        ans %= mod;
        return solvememo[pow] = ans;
    }

    static int dp(int color, long idx, int pow) {
        if (dp[color].containsKey(idx))
            return dp[color].get(idx);

        long left = 2 * idx;
        long right = 2 * idx + 1;
        long ansl = 0;
        long ansR = 0;
        if (exist(left)) {
            for (int j = 0; j < 6; j++) {
                if (can(left, color, j))
                    ansl += dp(j, left, pow - 1);
            }
            ansl %= mod;
        } else ansl = solve(pow - 1);

        if (exist(right)) {
            for (int j = 0; j < 6; j++) {
                if (can(right, color, j))
                    ansR += dp(j, right, pow - 1);
            }
            ansR %= mod;
        } else ansR = solve(pow - 1);
        long res = (ansl * ansR) % mod;
        dp[color].put(idx, (int) res);
        return (int) res;
    }

    private static boolean can(long node, int color, int j) {
        if (j == color || (Math.min(j, color) % 2 == 0 && Math.abs(j - color) == 1))
            return false;
        if (done.containsKey(node))
            return done.get(node) == j;
        return true;
    }

    public static void main(String[] args) throws IOException {

        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        HashMap<String, Integer> pos = new HashMap<>();
        pos.put("white", 0);
        pos.put("yellow", 1);
        pos.put("green", 2);
        pos.put("blue", 3);
        pos.put("red", 4);
        pos.put("orange", 5);
        k = sc.nextInt();
        int n = sc.nextInt();
        in = new HashSet<>();
        Max = 1l << k;
        done = new HashMap<>();
        dp = new HashMap[6];
        for (int i = 0; i < 6; i++)
            dp[i] = new HashMap<>();

        for (int i = 0; i < n; i++) {
            long cur = sc.nextLong();
            int c = pos.get(sc.next());
            done.put(cur, c);
            while (cur > 0) {
                in.add(cur);
                cur >>= 1;
            }
        }
        long ans = 0;
        solvememo = new long[k + 1];
        Arrays.fill(solvememo, -1);
        for (int i = 0; i < 6; i++) {
            if (can(1, 200, i))
                ans += dp(i, 1, k);
        }

        pw.println(ans % mod);

        pw.close();
    }


