/**
 * -----------------|___________|---------------------
 * CCCCCCCCC   OOOOOOOOOO   DDDDDDDD      EEEEEEEEE
 * CCCC        OOO    OOO   DD    DDD     EEEE
 * CCCC        OOO    OOO   DD     DDD    EEEEEEEEEE
 * CCCC        OOO    OOO   DD     DDDD   EEEE
 * CCCCCCCCC   OOOOOOOOOO   DDDDDDDDDDDD  EEEEEEEEEE
 * -----------------|___________|---------------------
 */

public class Main {
    private static final int MOD = 1000000007;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter sout = new PrintWriter(outputStream);

        int t = in.nextInt();
        lab:
        while (t-->0) {
            int n = in.nextInt();
            char[][] array = new char[2][n];
            for (int i = 0; i < 2; i++) {
                String str = in.nextToken();
                array[i] = str.toCharArray();
            }
            for (int i = 0; i < n; i++) {
                if (array[0][i] == '1' && array[1][i] == '1') {
                    sout.println("NO");
                    continue lab;
                }
            }
            sout.println("YES");
        }
        sout.close();
    }

    public static int binarySearch(long[] array, long value) {
        int left = 0, right = array.length - 1;
        while (left <= right) {
            int m = (left + right) / 2;
            if (array[m] == value)
                return m;
            else if (array[m] < value)
                left = m + 1;
            else
                right = m - 1;
        }
        return -1;
    }

    public static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    public static void sort(long[] a) {
        ArrayList<Long> l = new ArrayList<>();
        for (long i : a)
            l.add(i);
        Collections.sort(l);
        for (int i = 0; i < a.length; i++)
            a[i] = l.get(i);
    }

    private static int upperBound(int[] a, int low, int high, int element) {
        while (low < high) {
            int middle = low + (high - low) / 2;
            if (a[middle] > element)
                high = middle;
            else
                low = middle + 1;
        }
        return low;
    }

    public static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

