import java.util.*;
import java.io.*;
import static java.lang.Math.*;

public class a {
	static int n,m;
	static boolean[][] g;

	static long[][][] dp;

	static long tot = 0;

	static boolean works(int i, int j) {
		return i<n && j < m && min(i,j)>=0 && !g[i][j];
	}

	public static void main(String[] args) throws IOException{
		n =readInt();
		m = readInt();
		int q =readInt();

		g = new boolean[n][m];

		dp = new long[n][m][2];
		for (int i = n-1; i >= 0; i--) {
			for (int j = m-1; j >= 0; j--) {
				if (works(i+1,j)) dp[i][j][1]= 1+ dp[i+1][j][0];
				if (works(i,j+1))	dp[i][j][0] = dp[i][j+1][1]+1;
				tot += dp[i][j][1] + dp[i][j][0];
			}
		}
		long free = n*m;
		while(q-->0) {
			// You only need to update a diagonal or someth
			int x = readInt()-1, y = readInt()-1;
			g[x][y] =!g[x][y];
			if (g[x][y]) free--;
			else free++;

			// Recalculate everything on the diagonal
			// It's not the most efficient but probably the least mind numbing one
			int li = x, lj = y;
			for (; li < n-1; li++,lj++);
			//System.out.println(tot);
			for (int i =li; i >= 0; i--,lj--) {
				for (int j = lj+1; j >= lj-1; j--) {
					if (j < 0 || j >= m) continue;
					tot -= dp[i][j][1] + dp[i][j][0];
					//System.out.println("temp tot " + tot);
					dp[i][j][0] = dp[i][j][1] = 0;
					if (g[i][j]) {
					}
					else {
						if (works(i+1,j)) dp[i][j][1] = 1 + dp[i+1][j][0];
						if (works(i,j+1)) dp[i][j][0] = 1 + dp[i][j+1][1];
					}
					tot += dp[i][j][1] + dp[i][j][0];
					//System.out.println("new tot " + tot);
				}

			}

			out.println(tot + free);
			//System.out.println("-------------");

		}
		out.close();
	}

	static StringTokenizer st = new StringTokenizer("");
	static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	static PrintWriter out = new PrintWriter(System.out);

	static String read() throws IOException {
		if (st.hasMoreElements())
			return st.nextToken();
		return (st = new StringTokenizer(br.readLine())).nextToken();
	}

	static int readInt() throws IOException {
		return Integer.parseInt(read());
