import java.io.BufferedOutputStream;

public class RobotFactory {
    static PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

    static class Scanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public Scanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!this.tokenizer.hasMoreTokens()) {
                try {
                    this.tokenizer = new StringTokenizer(this.reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return this.tokenizer.nextToken();
        }

        public byte nextByte() {
            return Byte.parseByte(this.next());
        }

        public int nextInt() {
            return Integer.parseInt(this.next());
        }

        public long nextLong() {
            return Long.parseLong(this.next());
        }

        public double nextDouble() {
            return Double.parseDouble(this.next());
        }

        public String nextLine() {
            try {
                return this.reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
                return "";
            }
        }
    }

    private static int traverse(byte[][] factory, int row, int col, int cols) {
        Queue<Integer> toVisit = new LinkedList<>();
        toVisit.add(row*cols + col);
        int size = 0;
        while (!toVisit.isEmpty()) {
            int loc = toVisit.remove();
            int locRow = loc / cols;
            int locCol = loc % cols;
            byte state = factory[locRow][locCol];
            if (((state >> 4) & 1) != 1) {
                factory[locRow][locCol] |= 1 << 4;
                size++;
                if (((state >> 3) & 1) == 0) {
                    toVisit.add(cols*(locRow - 1) + locCol);
                }
                if (((state >> 1) & 1) == 0) {
                    toVisit.add(cols*(locRow + 1) + locCol);
                }
                if ((state & 1) == 0) {
                    toVisit.add(cols*locRow + locCol - 1);
                }
                if (((state >> 2) & 1) == 0) {
                    toVisit.add(cols*locRow + locCol + 1);
                }
            }
        }
        return size;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner();
        int n = input.nextInt();
        int m = input.nextInt();
        byte[][] factory = new byte[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                factory[i][j] = input.nextByte();
            }
        }
        PriorityQueue<Integer> roomSizes = new PriorityQueue<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int size = traverse(factory, i, j, m);
                if (size > 0) {
                    roomSizes.add(size);
                }
            }
        }
        while (!roomSizes.isEmpty()) {
            out.print(roomSizes.poll());
            out.print(' ');
        }
        out.println();
        out.close();
    }
}

