			for(int x : ans) {
				gcd = __gcd(gcd, x);
			}
			for(int i = 1 ; i <= gcd ; i++) {
				if(gcd % i == 0) {
					pw.print(i + " ");
				}
			}
			pw.println();
		}
		pw.close();
	}

	public static int __gcd(int a, int b) {
		if (b != 0) {
			return __gcd(b, a % b);
		} else {
			return a;
		}
	}

	public static int lower_bound(ArrayList<Integer> ar, int k) {
		int s = 0;
		int e = ar.size();
		while (s != e) {
			int mid = s + e >> 1;
			if (ar.get(mid) < k) {
				s = mid + 1;
			} else {
				e = mid;
			}
		}
		if (s == ar.size()) {
			return -1;
		}
		return s;
	}

	public static int upper_bound(ArrayList<Integer> ar, int k) {
		int s = 0;
		int e = ar.size();
		while (s != e) {
			int mid = s + e >> 1;
			if (ar.get(mid) <= k) {
				s = mid + 1;
			} else {
				e = mid;
			}
		}
		if (s == ar.size()) {
			return -1;
		}
		return s;
	}
}

