        int p1;
        int p2;
        public Pair(int p1,int p2) {
            this.p1 = p1;
            this.p2 = p2;
        }
    }

    public static void main(String[] args) {
        int n = in.nextInt();
        int[] a = new int[n+1];
        int[] b = new int[n+1];
        for (int i = 1;i <= n;i++) {
            a[i] = in.nextInt();
        }
        for (int i = 1;i <= n;i++) {
            b[i] = in.nextInt();
        }
        TreeSet<Integer> f = new TreeSet<>();
        for (int i = 1;i <= n;i++) {
            f.add(i);
        }
        int[] pre = new int[n+1];
        Queue<Pair> Q = new ArrayDeque<>();
        Q.add(new Pair(n,n)); //before after
        while(!Q.isEmpty()) {
            Pair p = Q.poll();
            int u = p.p1;
            int bU = p.p2;
            if (u - a[u] <= 0) {
                pre[0] = bU;
                break;
            }
            Integer l = u-a[u];
            while((l = f.ceiling(l))!= null) {
                if (l > u)break;
                pre[l] = bU;
                Q.add(new Pair(Math.min(n,l+b[l]),l));
                f.remove(l);
            }
        }

        if (pre[0] == 0) {
            out.println(-1);
        } else {
            ArrayList<Integer> ans = new ArrayList<>();
            int p = 0;
            ans.add(0);
            while((p = pre[p])!=n) {
                ans.add(p);
            }
            out.println(ans.size());
            for (int i = ans.size()-1;i >= 0;i--) {
