public class _116 {
    static long mod = 998244353;;
    static long [] fac;
    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int t = 1;
        initFac(503);
        long [][] combo = new long[502][502];
        for (int i = 1; i <= 501; i++) {
            for (int j = 0; j <= 501; j++) {
                if (j > i) continue;
                if (j == 0 || j == i) combo[i][j] = 1;
                else {
                    combo[i][j] = (combo[i - 1][j - 1] + combo[i - 1][j]) % mod;
                }
            }
        }
        long [][] power = new long[502][502];
        for (int i = 0; i <= 501; i++) {
            long p = 1;
            for (int j = 0; j <= 501; j++) {
                power[i][j] = p;
                p = (p * i) % mod;
            }
        }
        while (t-- > 0) {
            int n = sc.nextInt();
            int x = sc.nextInt();
            if (x < n) {
                out.println(pow(x, n));
                continue;
            }
            // number of ways to get one unique winner
            long [][] dp = new long[n + 1][x + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = i; j <= x; j++) {
                    if (i == 1) {
                        dp[i][j] = j;
                        continue;
                    }
                    long res = 0;
                    // choose number of people less than or equal to i - 1
                    for (int small = 0; small <= i; small++) {
                        long pick = (power[i - 1][small] * combo[i][small]) % mod;
                        res = (res + (pick * dp[i - small][j - (i - 1)]) % mod) % mod;
                    }
                    dp[i][j] = res;
                }
            }
            long ans = pow(x, n);
            ans = (ans - dp[n][x]) % mod;
            if (ans < 0) ans += mod;
            out.println(ans);
        }
        out.close();
    }

    static void initFac(long n) {
        fac = new long[(int)n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1]  * i) % mod;
        }
    }



    static long nck(int n, int k) {
        if (n < k)
            return 0;
        long den = inv((int) (fac[k] * fac[n - k] % mod));
        return fac[n] * den % mod;
    }

    static long pow(long b, long e) {
        long ans = 1;
        while (e > 0) {
            if (e % 2 == 1)
                ans = ans * b % mod;
            e >>= 1;
            b = b * b % mod;
        }
        return ans;
    }

    static long inv(long x) {
        return pow(x, mod - 2);
    }


    static void sort(int[] a) {
        ArrayList<Integer> q = new ArrayList<>();
        for (int i : a) q.add(i);
        Collections.sort(q);
        for (int i = 0; i < a.length; i++) a[i] = q.get(i);
