import java.util.*;
import java.io.*;
public class Solution {

    public static void solve(InputReader in, PrintWriter out) {
       int t = in.nextInt();
       while (t-- > 0) {
           int n = in.nextInt();
           int m = in.nextInt();
           String st = in.next();
           int x = 1, y = 1, mx = 1, my = 1, cx = 1, cy = 1;
           int len = st.length();
           for (int i = 0; i < len; i++) {
               if (st.charAt(i) == 'R') {
                   cy++;
                   if (cy > m) {
                       break;
                   }
                   my = Math.max(my, cy);
               } else if (st.charAt(i) == 'L') {
                   cy--;
                   if (cy < 1) {
                       if (my + 1 <= m) {
                           y++;
                           cy = 1;
                           my++;
                       } else {
                           break;
                       }
                   }
               } else if (st.charAt(i) == 'U') {
                   cx--;
                   if (cx < 1) {
                       if (mx + 1 <= n) {
                           x++;
                           cx = 1;
                           mx++;
                       } else {
                           break;
                       }
                   }
               } else {
                   cx++;
                   if (cx > n) {
                       break;
                   }
                   mx = Math.max(mx, cx);
               }
           }
           out.println(x + " " + y);
       }
    }

