import java.io.*;
import java.util.Arrays;
import java.util.Random;
import java.util.Stack;
import java.util.StringTokenizer;

public class codeforces_753_E2 {
    private static void solve(FastIOAdapter io) {
        int n = io.nextInt();
        int m = io.nextInt();
        char[][] a = new char[n][];
        for (int i = 0; i < n; i++) {
            a[i] = io.next().toCharArray();
        }
        int[][] lengths = new int[n][m];
        int[][] indices = new int[n][m];
        int x = 0, y = 0;
        int max = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (lengths[i][j] == 0) { // we did not check this
                    Stack<int[]> stack = new Stack<>();
                    stack.add(new int[]{i, j});
                    lengths[i][j] = -1; // we were here
                    indices[i][j] = 0;
                    int length = 1;
                    int cycle = 0;
                    int cycX = -1, cycY = -1;
                    while (true) {
                        int[] xy = stack.peek();
                        int xc = xy[0], yc = xy[1];
                        if (a[xc][yc] == 'U') {
                            xc--;
                        } else if (a[xc][yc] == 'D') {
                            xc++;
                        } else if (a[xc][yc] == 'L') {
                            yc--;
                        } else yc++;
                        if (xc < 0 || xc >= n || yc < 0 || yc >= m) {
                            break;
                        } else if (lengths[xc][yc] < 0) {
                            cycle -= indices[xc][yc] - 1;
                            length = cycle + 1;
                            cycX = xc;
                            cycY = yc;
                            break;
                        } else if (lengths[xc][yc] > 0) {
                            length = lengths[xc][yc] + 1;
                            break;
                        } else {
                            lengths[xc][yc] = -1;
                            indices[xc][yc] = ++cycle;
                            stack.add(new int[]{xc, yc});
                        }
                    }
                    boolean isCycle = cycX != -1;
                    int len = isCycle ? cycle : length;
                    while (!stack.isEmpty()) {
                        int[] xy = stack.pop();
                        lengths[xy[0]][xy[1]] = len;
                        if (isCycle) {
                            if (xy[0] == cycX && xy[1] == cycY) {
                                isCycle = false;
                                len = length;
                            }
                        } else len++;
                    }
                    if (max < lengths[i][j]) {
                        max = lengths[i][j];
                        x = i + 1;
                        y = j + 1;
                    }
                }
            }
        }
        io.out.println(x + " " + y + " " + max);
    }

    public static void main(String[] args) throws Exception {
        try (FastIOAdapter ioAdapter = new FastIOAdapter()) {
            int count = 1;
            count = ioAdapter.nextInt();
            while (count-- > 0) {
                solve(ioAdapter);
            }
        }
    }

    static void ruffleSort(int[] arr) {
        int n = arr.length;
        Random rnd = new Random();
        for (int i = 0; i < n; ++i) {
            int tmp = arr[i];
            int randomPos = i + rnd.nextInt(n - i);
            arr[i] = arr[randomPos];
            arr[randomPos] = tmp;
        }
        Arrays.sort(arr);
    }

    static class FastIOAdapter implements AutoCloseable {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        public PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter((System.out))));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens())
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            return st.nextToken();
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
                return null;
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        long[] readArrayLong(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        @Override
        public void close() throws Exception {
            out.flush();
            out.close();
            br.close();
        }
    }
}

