#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 7, inf = 2e9 + 9, mod = 998244353;
long long pw(long long x, int k) {
  long long res = 1LL;
  while (k) {
    if (k & 1) {
      res *= x;
      res %= mod;
    }
    k >>= 1;
    x *= x;
    x %= mod;
  }
  return res;
}
long long c(int n, int k) {
  if (k < 0) return 0;
  long long res = 1;
  for (int i = n - k + 1; i < n + 1; ++i) {
    res *= i;
    res %= mod;
  }
  for (int i = 2; i < k + 1; ++i) {
    res *= pw(i, mod - 2);
    res %= mod;
  }
  return res;
}
char a[2];
bool is(char c[2]) { return a[0] == c[0] and a[1] == c[1]; }
void solve() {
