  for (int i = 0; i < n; ++i) {
    scanf("%s", &a);
    for (int i = 0; i < 2; ++i) {
      if (a[i] == 'B')
        tb++;
      else if (a[i] == 'W')
        tw++;
    }
    if (is("??")) __++;
    if (is("BB") or is("WW")) same = true;
    switch (a[0]) {
      case 'B':
        b_ = true;
        break;
      case 'W':
        w_ = true;
        break;
      case '?':
        e++;
        break;
    }
    switch (a[1]) {
      case 'B':
        _b = true;
        break;
      case 'W':
        _w = true;
        break;
      case '?':
        e++;
        break;
    }
  }
  int d = abs(tb - tw);
  long long res = c(e, (e - d) / 2);
  if (!same) {
    res -= pw(2, __);
    if (!_w and !b_) res++;
    if (!w_ and !_b) res++;
    res = (res + mod) % mod;
  }
  printf("%I64d", res);
}
