    // Fermats Little Theorem:
    // (a^p - a) % p = 0
    // => a^p % p - a % p = 0
    // => a^p % p = a % p
    // => a^(p - 1) % p = (a * a^-1) % p
    // => a^(p - 1) %  p = 1 % p
    // => a^(p - 2) % p = a^-1 % p

    static long binPow(long a, long b){
        long res = 1;
        while(b > 0){
            a = a % mod;
            if((b&1) == 1){
                res = (res * a) % mod;
            }
            b >>= 1;
            a = (a * a) % mod;
        }
        return res;
    }

    static long modInverse(long a){
        return binPow(a, mod - 2);
    }

    static long mul(long a, long b){
        return (a * b) % mod;
    }

    static long nCr(int n, int r){
        long res = mul(fact[n], invFact[r]);
        res = mul(res, invFact[n - r]);
        return res;
    }

    public static void main(String args[]) throws IOException{
        int n;
        n = Integer.parseInt(br.readLine());
        String [] ls = new String[n];
        boolean full = false;
        int black = 0, white = 0;
        for(int i = 0; i < n; ++i){
            ls[i] = br.readLine();
            if(ls[i].charAt(0) == 'W')
                white++;
            if(ls[i].charAt(0) == 'B')
                black++;
            if(ls[i].charAt(1) == 'W')
                white++;
            if(ls[i].charAt(1) == 'B')
                black++;
            if(ls[i].charAt(0) != '?' && ls[i].charAt(0) == ls[i].charAt(1)){
                full = true;
            }
        }
        if(black > n || white > n){
            pw.println(0);
            return;
        }

        fact = new long[2 * n + 1];
        invFact = new long[2 * n + 1];
        fact[0] = 1;
        invFact[0] = 1;
        for(int i = 1; i <= 2 * n; ++i){
            fact[i] = mul(fact[i - 1], i);
            invFact[i] = modInverse(fact[i]);
        }
        int empty = 2 * n - black - white;
        long ans = nCr(empty, n - black);
        if(full){
            pw.println(ans);
            return;
        }
        long invalid = 1;
        boolean WB = true, BW = true;
        for(int i = 0; i < n; ++i){
            if(ls[i].charAt(0) == '?' && ls[i].charAt(1) == '?'){
                invalid = mul(invalid, 2);
            } 
            if(ls[i].charAt(0) == 'B' || ls[i].charAt(1) == 'W'){
                WB = false;
            }
            if(ls[i].charAt(0) == 'W' || ls[i].charAt(1) == 'B'){
                BW = false;
            }
        }
        if(WB)
            invalid--;
        if(BW)
            invalid--;
        ans = ans - invalid;
        pw.println(ans);
    }
}


