				for (int j = 0; j < m; j ++)
				{
					if (i == x && j == y)
					{
						s.append('L');
						continue;
					}
					if (grid[i][j] == 0)
					{
						s.append('#');
						continue;
					}
					if (grid[i][j] == 1)
					{
						s.append('.');
						continue;
					}
					s.append('+');
				}
				pw.println(s);
			}
		}
		pw.close();
	}
	static void floodfill(int row, int col)
	{
		if (row < 0 || row >= n || col < 0 || col >= m || grid[row][col] <= 0)
		{
			return;
		}
		int count = 0;
		int free = 0;
		for (int i = 0; i < 4; i ++)
		{
			if (row + dx[i] < 0 || row + dx[i] >= n || col + dy[i] < 0 || col + dy[i] >= m)
			{
				continue;
			}
			count += (grid[row + dx[i]][col + dy[i]] < 0?1:0);
			free += Math.abs(grid[row+dx[i]][col+dy[i]]);
		}
		if (row == x && col == y)
		{
			free = 6;
			count = 6;
		}
		if ((free-count <= 1 && count >= 1) ||(row == x && col==y))
		{
			grid[row][col] = -1;
			for (int i = 0; i < 4; i ++)
			{
				floodfill(row+dx[i],col+dy[i]);
			}
		}
		else
		{
			return;
		}
	}
}

