import java.io.*;
import java.util.*;

public class CF1615E extends PrintWriter {
	CF1615E() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF1615E o = new CF1615E(); o.main(); o.flush();
	}

	int[] eo; int[][] ej;
	void append(int i, int j) {
		int o = eo[i]++;
		if (o >= 2 && (o & o - 1) == 0)
			ej[i] = Arrays.copyOf(ej[i], o << 1);
		ej[i][o] = j;
	}
	boolean[] used; int[] pp, dd, xx;
	int dfs(int p, int i, int d) {
		pp[i] = p;
		dd[i] = d;
		int x = i;
		for (int o = eo[i]; o-- > 0; ) {
			int j = ej[i][o];
			if (j != p) {
				int y = dfs(i, j, d + 1);
				if (dd[x] < dd[y])
					x = y;
			}
		}
		return xx[i] = x;
	}
	int[] pq, iq; int cnt;
	boolean lt(int i, int j) {
		return dd[xx[i]] - dd[i] > dd[xx[j]] - dd[j];
	}
	int p2(int p) {
		return (p *= 2) > cnt ? 0 : p < cnt && lt(iq[p + 1], iq[p]) ? p + 1 : p;
	}
	void pq_up(int i) {
		int j, p, q;
		for (p = pq[i]; (q = p / 2) > 0 && lt(i, j = iq[q]); p = q)
			iq[pq[j] = p] = j;
		iq[pq[i] = p] = i;
	}
	void pq_dn(int i) {
		int j, p, q;
		for (p = pq[i]; (q = p2(p)) > 0 && lt(j = iq[q], i); p = q)
			iq[pq[j] = p] = j;
		iq[pq[i] = p] = i;
	}
	void pq_add(int i) {
		pq[i] = ++cnt; pq_up(i);
	}
	int pq_remove_first() {
		int i = iq[1], j = iq[cnt--];
		if (j != i) {
			pq[j] = 1; pq_dn(j);
		}
		pq[i] = 0;
		return i;
	}
	long solve(int u, int v) {
		if (u >= v)
			return (long) u * v;
		int a = (u + v) / 2;
		return (long) a * (u + v - a);
	}
	long solve(int r, int w, int wb) {
		if (r >= wb)
			return (long) w * (r - wb);
		return -solve(w, wb - r);
	}
	void main() {
		int n = sc.nextInt();
		int k = sc.nextInt();
		eo = new int[n]; ej = new int[n][2];
		for (int h = 0; h < n - 1; h++) {
			int i = sc.nextInt() - 1;
			int j = sc.nextInt() - 1;
			append(i, j);
			append(j, i);
		}
		used = new boolean[n]; pp = new int[n]; dd = new int[n]; xx = new int[n];
		dfs(-1, 0, 0);
		int w = 0, r = 0;
		long ans = solve(r, w, n - r - w);
		pq = new int[n]; iq = new int[n + 1];
		pq_add(0);
		while (cnt > 0 && r < k) {
			int i = pq_remove_first();
			int x = xx[i];
			w += dd[x] - dd[i]; r++;
			ans = Math.max(ans, solve(r, w, n - r - w));
			used[x] = true;
			for (i = pp[x]; i != -1 && !used[i]; i = pp[x = i]) {
				used[i] = true;
				for (int o = eo[i]; o-- > 0; ) {
					int j = ej[i][o];
					if (j != x && j != pp[i])
						pq_add(j);
				}
			}
		}
		if (r < k)	// r + w == n
			if (r + r < n) {
				if (k + k < n)
					r = k;
				else
					r = n / 2;
				w = n - r;
				ans = Math.max(ans, (long) w * r);
			}
