    public static void solve(int arr[],int n, BufferedWriter bw) throws IOException{
        TreeSet<Integer> set=new TreeSet<>();
        for (int i = 1; i <= n ; i++) {
            set.add(i);
        }
        for (int i = 0; i < n; i++) {
            if(set.contains(arr[i])){
                set.remove(arr[i]);
                arr[i]=-1;
            }
        }
        int ans=0;
        boolean flag=false;
        for (int i = 0; i < n; i++) {
            if(arr[i]!=-1){
                int val=(arr[i]-1)/2;
                if(set.floor(val) != null){
                   ans++;
                   set.remove(set.floor(val));
                }
                else {
                    flag=true;
                    break;
                }
            }
        }
        if(flag){
            bw.write("-1");
        }
        else {
            bw.write(ans+"");
        }
        bw.newLine();
    }
    public static void main(String[] args)throws IOException {
        Reader scan=new  Reader();
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        int t=scan.nextInt();
        while (t-->0) {
            int n=scan.nextInt();
            int[] arr=fillArray(n,scan);
            solve(arr,n,bw);
        }
        bw.flush();
    }
    private static int[] fillArray(int n, Reader scan)
    {
        int[] arr=new int[n];
        for (int i = 0; i < n; i++) {
            arr[i]=scan.nextInt();
        }
        return arr;
    }

    //FAST READER
    static class Reader {
        public int BS = 1<<16;
        public char NC = (char)0;
        byte[] buf = new byte[BS];
        int bId = 0, size = 0;
        char c = NC;
        double num = 1;
        BufferedInputStream in;

        public Reader() {
            in = new BufferedInputStream(System.in, BS);
        }

        public Reader(String s) throws FileNotFoundException {
            in = new BufferedInputStream(new FileInputStream(new File(s)), BS);
        }

        public char nextChar(){
            while(bId==size) {
                try {
                    size = in.read(buf);
                }catch(Exception e) {
                    return NC;
                }
                if(size==-1)return NC;
                bId=0;
            }
            return (char)buf[bId++];
        }

        public int nextInt() {
            return (int)nextLong();
        }

        public long nextLong() {
            num=1;
            boolean neg = false;
            if(c==NC)c=nextChar();
            for(;(c<'0' || c>'9'); c = nextChar()) {
                if(c=='-')neg=true;
            }
            long res = 0;
            for(; c>='0' && c <='9'; c=nextChar()) {
                res = (res<<3)+(res<<1)+c-'0';
                num*=10;
            }
            return neg?-res:res;
        }

        public double nextDouble() {
            double cur = nextLong();
            return c!='.' ? cur:cur+(cur < 0 ? -1*nextLong()/num : nextLong()/num);
        }

        public String next() {
            StringBuilder res = new StringBuilder();
            while(c<=32)c=nextChar();
            while(c>32) {
                res.append(c);
                c=nextChar();
            }
            return res.toString();
        }
    }
}

