import java.util.HashSet;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        String x=Long.toBinaryString(sc.nextLong());
        String y=Long.toBinaryString(sc.nextLong());
        HashSet<String> set=new HashSet<>();
        HashSet<String> invalids=new HashSet<>();
        set.add(x);
        while(!set.contains(y)) {
            boolean flag=false;
            for(String str:(HashSet<String>)set.clone()) {
                invalids.add(str);
                set.remove(str);

                String str1=reserve(str+"0");
                if(!invalids.contains(str1)) {
                    set.add(str1);
                    flag=true;
                }
                String str2=reserve(str+"1");
                if(!invalids.contains(str2) && str2.length()<=y.length()) {
                    set.add(str2);
                    flag=true;
                }
            }
            if(!flag)
                break;
        }
        if(set.contains(y))
            System.out.println("YES");
        else
            System.out.println("NO");
    }

    private static String reserve(String str) {
        char[] ch=str.toCharArray();
        boolean flag=false;
        String ret="";
        for(int i=ch.length-1;i>=0;i--) {
            if(!flag && ch[i]!='0')
                flag=true;
            if(flag)
                ret+=ch[i];
        }
        return ret;
    }
}

