        BufferedReader br;
        StringTokenizer st;
        public Reader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() {
            return Double.parseDouble(next());
        }
        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String args[]) {
        Reader r = new Reader();

        int n = r.nextInt();
        for (int i = 0; i < n; i++) {
            String a = r.next();
            String b = r.next();
            String o = "";

            int ac = a.length() - 1;
            int bc = b.length() - 1;
            while (ac > -1 && bc > -1) {
                int as = a.charAt(ac) - '0';
                int bs = b.charAt(bc) - '0';
                if (bs < as) {
                    if (bc == 0) break;
                    bc--;
                    if (b.charAt(bc) != '1') {
                        ac = Integer.MAX_VALUE;
                        break;
                    }
                    bs = Integer.parseInt(b.substring(bc, bc + 2));
                }
                o = (char)(bs - as + '0') + o;
                ac--;
                bc--;
            }
            if (bc > -1) {
                o = b.substring(0, bc + 1) + o;
            }
            for (int j = 0; j < o.length(); j++) {
                if (o.charAt(j) != '0') {
                    o = o.substring(j);
                    break;
                }
            }
            System.out.println((ac > -1) ? -1 : o);
        }
    }
}

