int m, n;
bool can_joy(vector<vector<int>> p, ll joy) {
  bool flag1 = false;
  for (int i = 0; i < m; i++) {
    int found = 0;
    for (int j = 0; j < n; j++) {
      found += p[i][j] >= joy;
    }
    if (found >= 2) {
      flag1 = true;
      break;
    }
  }
  if (!flag1) return false;
  bool flag2;
  for (int j = 0; j < n; j++) {
    flag2 = false;
    for (int i = 0; i < m; i++) {
      flag2 |= p[i][j] >= joy;
    }
    if (!flag2) return false;
  }
  return true;
}
