import java.io.*;
import java.util.Arrays;
import java.util.HashSet;
import java.util.StringTokenizer;

/**
 * Accomplished using the EduTools plugin by JetBrains https://plugins.jetbrains.com/plugin/10081-edutools
 */


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, in, out);
        out.close();
    }

    public static class Task {

        public void solve(int cnt, InputReader in, PrintWriter out) {
            cnt = in.nextInt();
            for (int cc = 0; cc < cnt; cc++) {
                int m = in.nextInt();
                int n = in.nextInt();
                int maxMin = Integer.MAX_VALUE;
                int[][] joy = new int[m][n];
                //每个朋友最大的joy，和对应商店
                int[][] maxJoy = new int[n][2];
                for (int i = 0; i < m; i++) {
                    for (int j = 0; j < n; j++) {
                        joy[i][j] = in.nextInt();
                        if (joy[i][j] >= maxJoy[j][0]) {
                            maxJoy[j][0] = joy[i][j];
                            maxJoy[j][1] = i;
                        }
                    }
                }
                //遍历每个朋友最大joy对应的商店，因为最多选n-1家，所以如果各自不同，就要抛弃一家
                HashSet<Integer> shops = new HashSet<>();
                for (int i = 0; i < n; i++) {
                    shops.add(maxJoy[i][1]);
                    maxMin = Math.min(maxJoy[i][0], maxMin);
                }
                if (shops.size() >= n) {
                    //抛弃一家
                    //找到每一行第二大的
                    int ret = 0;
                    for(int i=0;i<m;i++) {
                        for(int j=0;j<n;j++) {
                            Arrays.sort(joy[i]);
                            ret = Math.max(ret, joy[i][n-2]);
                        }
                    }
                    maxMin = Math.min(ret, maxMin);
                }
                out.println(maxMin);
            }
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
