                rows.get(x).put(y, i);

                cols.putIfAbsent(y, new TreeMap<>());
                cols.get(y).put(x, i);

            }

            for (int i = 0; i < n; i++) {
                int x = bombs[i][0], y = bombs[i][1];

            }

            List<Integer> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
