                    list.add(dfs(i));
                }
            }

            Collections.sort(list, Comparator.reverseOrder());
            int time = 0;
            int res = 0;
            for (int i : list) {
                if (time >= i) {
                    res = max(time - 1, i);
                    break;
                }
                res = time;
                time++;
            }
            pw.println(max(res, 0));
        }

