        if (vis[i]) {
            return INF;
        }
        vis[i] = true;
        int min = bombs[i][2], x = bombs[i][0], y = bombs[i][1];

        Integer upper = rows.get(x).higherKey(y);
        if (upper != null && y + k >= upper) {
            int temp = dfs(rows.get(x).get(upper));
            min = min(min, temp);
        }

        Integer lower = rows.get(x).lowerKey(y);
        if (lower != null && y - k <= lower) {
            int temp = dfs(rows.get(x).get(lower));
            min = min(min, temp);
        }


        Integer right = cols.get(y).higherKey(x);
        if (right != null && x + k >= right) {
            int temp = dfs(cols.get(y).get(right));
            min = min(min, temp);
        }

        Integer left = cols.get(y).lowerKey(x);
        if (left != null && x - k <= left) {
            int temp = dfs(cols.get(y).get(left));
            min = min(min, temp);
        }

        return min;
    }

