  ans.clear();
  int cnt = 0;
  for (int i = 0; i < n; i++) {
    if (s[i] == '*') {
      cnt++;
    } else {
      vec.push_back(cnt * k);
      cnt = 0;
    }
  }
  vec.push_back(cnt * k);
