  string fin = "";
  reverse(ans.begin(), ans.end());
  for (int i = 0; i < ans.size(); i++) {
    string str = string(ans[i], 'b');
    fin = fin + str;
    if (i != ans.size() - 1) fin = fin + 'a';
  }
