            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) ar[j] = Integer.parseInt(st.nextToken());
            int ans = Integer.MAX_VALUE;
            for (int j = 0; j < 3; j++) {
                 for (int k = 0; k < 3; k++) {
                    //j = # of 1; k = # of 2
                    int[][] mod3 = new int[10][2];
                    mod3[0][0] = 1;
                    mod3[0][1] = 0;
                    for (int l = 0; l < 10; l++) mod3[l][1] = Integer.MAX_VALUE;
                    for (int l = 0; l <= j; l++) {
                        for (int m = 0; m <= k; m++) {
                            mod3[l + m * 2][0] = 1;
                            mod3[l + m * 2][1] = Math.min(l + m,  mod3[l + m * 2][1]);
                        }
                    }
                    int mx = 0;
                    for (int l = 0; l < n; l++) {
                        int mod = ar[l] % 3;
                        int mn = Integer.MAX_VALUE;
                        while (mod <= ar[l] && mod <= 9){
                            if(mod3[mod][0] == 1) {
                                mn = Math.min((ar[l] - mod)/3, mn);
                            }
                            mod += 3;
                        }
                        mx = Math.max(mx, mn);
                    }
                    if(mx == Integer.MAX_VALUE) continue;
                    ans = Math.min(ans, mx + j + k);
                }
            }
            System.out.println(ans);
        }
    }
}

