    static long max = Long.MAX_VALUE;

    static long call(List<Long> list, long x, long sum, long k, long n) {
        long val = list.get(0) - x, tot = sum - x, ans = x;
        if (tot <= k) {
            return ans;
        }
        for (long i = n - 1; i > 0; i--) {
            tot += (val - list.get((int) i));
            ans++;
            if (k >= tot) {
                return ans;
            }
        }
        return max;
    }

