        long f[]=new long[n+1],in[]=new long[n+1];
        f[0]=in[0]=1;
        for(i=1;i<=n;i++) f[i]=f[i-1]*i%M;
        in[n]=power(f[n],M-2);
        for(i=n-1;i>0;i--) in[i]=in[i+1]*(i+1)%M;

        long ans=0;
        for(i=0;i+k<=one.size();i++)
        {
            int z=0,o=k,j;
            for(j=i+1;j<i+k;j++)
            z+=one.get(j)-one.get(j-1)-1;
            if(i==0) z+=one.get(i);
            else z+=one.get(i)-one.get(i-1)-1;
            if(i+k<one.size()) z+=one.get(i+k)-one.get(i+k-1)-1;
            else z+=n-one.get(i+k-1)-1;

            //System.out.println(z+" "+o);
            long cur=f[z+o]*in[o]%M*in[z]%M;
            if(i>0)
            {
                o--;
                z=0;
                for(j=i;j<i+k;j++) z+=one.get(j)-one.get(j-1)-1;

                cur-=f[z+o]*in[o]%M*in[z]%M;
                cur=(cur+M)%M;
            }
            //System.out.println(cur);
            ans=(ans+cur)%M;
        }
        System.out.println(ans);
    }

    static long M=998244353;
    static long power(long a,long b)
    {
        long res=1;
        while(b!=0)
        {
            if(b%2==1) res=res*a%M;
            b>>=1;
            a=a*a%M;
        }
        return res;
    }
}

