		}
		if(exploreRight&&r!=-1) {
			dfs(r,cost);
		}
		return expand[at];
	}
	public static void init(int at, int d, int p) {
		depth[at]=d;
		parent[at]=p;
		if(a[at][0]!=-1) init(a[at][0],d+1,at);
		inorder.add(at);
		id[at]=inorder.size()-1;
		if(a[at][1]!=-1) init(a[at][1],d+1,at);
	}
